insert into public.site_settings (id, name, role, tagline, hero_supporting_copy, bio, availability_text, email, linkedin_url, github_url, resume_url, footer_copy)
values
  (1, 'Gerikah', 'UI/UX Designer & Frontend Developer', 'I design it. Then I build it.', 'I design thoughtful interfaces and build them into real, working products.', 'I''m Gerikah, a Computer Engineer who enjoys both designing and building. I bring UI/UX thinking and frontend development together, from shaping an interface to connecting the data behind it.', '', 'aldaygerikah@gmail.com', 'https://www.linkedin.com/in/gerikah-alday/', 'https://github.com/gerikah', '', 'UI/UX Designer. Frontend Developer. Computer Engineer.')
insert into public.projects (id, title, slug, project_number, category, short_description, overview, role, tools, year, project_type, status, live_url, repository_url, cover_image_url, cover_alt, is_published, sort_order, created_at, updated_at)
values
  ('11111111-1111-4111-8111-111111111111', 'Off The Rack', 'off-the-rack', 1, 'E-commerce / Full-stack website', 'A responsive digital storefront for one-of-one and upcycled fashion.', 'A responsive storefront that brings product browsing, categories, availability, and custom inquiries together with Supabase-powered product administration.', 'UI/UX design, frontend development, database/admin integration', array['Next.js', 'TypeScript', 'Supabase', 'Vercel']::text[], null, 'Full-stack website', '', '', '', '/images/off-the-rack/hero.png', 'Off The Rack storefront screens shown in the original project presentation', true, 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222222222', 'Marci Metzger Homes', 'marci-metzger-homes', 2, 'Real Estate / Homepage redesign', 'An independent redesign that turns a real-estate homepage into a clearer editorial experience.', 'An independent redesign concept for a real-estate homepage, using a responsive single-page layout and an editorial visual system while preserving the provided copy and source photography. This is a concept, not an official client engagement.', 'UI/UX redesign and frontend development', array['HTML', 'CSS', 'JavaScript', 'Node/npm', 'Playwright', 'Vercel']::text[], null, 'Independent redesign concept', '', '', '', '/images/marci/hero.png', 'Marci Metzger Homes independent homepage redesign shown in the original project presentation', true, 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('33333333-3333-4333-8333-333333333333', 'Ground Control Station', 'ground-control-station', 3, 'Drone monitoring / Web & mobile interface', 'A ground-control interface bringing flight records, telemetry, and mission views into one dashboard.', 'Web and mobile screens for LIPAD GCS, a ground control station interface. The supplied screens show system status, flight records, analytics, and a drone-stream view with camera and telemetry information.', '', array[]::text[], null, 'Web & mobile interface', '', '', '', '/images/ground-control-station/hero.png', 'LIPAD ground control station dashboard presented on laptop and mobile screens', true, 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('44444444-4444-4444-8444-444444444444', 'Riftbound', 'riftbound', 4, 'Game UI / Mobile RPG', 'A pixel-art game interface with hero selection, equipment, quests, and battle screens.', 'A game UI design presented through Riftbound mobile RPG screens. The supplied designs include a home view, hero selection, equipment inventory, and a battle interface, with pixel-art characters and a forest visual setting.', '', array[]::text[], null, 'Game UI design', '', '', '', '/images/riftbound/hero.png', 'Riftbound game UI presentation showing home, hero selection, and battle screens', true, 4, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('55555555-5555-4555-8555-555555555555', 'Task Mate', 'task-mate', 5, 'Product UX / Mobile wireframe', 'A connected mobile wireframe mapping account access, task lists, settings, and support.', 'The Task Mate wireframe documents a task-management mobile interface. It links welcome and account screens to a dashboard, task entry, navigation, settings, feedback, and support.', '', array[]::text[], null, 'Mobile wireframe', '', '', '', '/images/task-mate/wireframe.jpg', 'Task Mate mobile wireframe map with connected account, dashboard, task entry, and settings screens', true, 5, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('66666666-6666-4666-8666-666666666666', 'Study Buddies', 'study-buddies', 6, 'Product UX / User flows', 'User flows for account access, study-partner matching, and chat.', 'A Study Buddies flowchart covering login, registration, password recovery, profile setup, study-partner matching, and chat. The document separates the main view, navigation, and individual account and communication processes.', '', array[]::text[], null, 'User-flow documentation', '', '', '', '/images/study-buddies/flowchart.jpg', 'Study Buddies flowchart showing account access, matching, chat, and navigation paths', true, 6, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('77777777-7777-4777-8777-777777777777', 'DropSafe', 'dropsafe', 7, 'Systems / Delivery & retrieval flows', 'A system flowchart connecting delivery, locker access, retrieval, and the resident dashboard.', 'The DropSafe diagram maps a delivery-locker system across initialization, delivery, retrieval, and the user dashboard. It documents OTP and RFID checks, locker status updates, and notification paths.', '', array[]::text[], null, 'System-flow documentation', '', '', '', '/images/dropsafe/flowchart.jpg', 'DropSafe system flowchart with initialization, delivery, retrieval, and resident dashboard lanes', true, 7, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('88888888-8888-4888-8888-888888888888', 'E-Registered Messaging System', 'e-registered-messaging-system', 8, 'Systems / Use cases & user flows', 'Use-case and user/system diagrams for registered messaging, sender verification, and campaigns.', 'The supplied E-Registered Messaging System diagrams document customer and administrator use cases, sender verification, individual messaging, and campaign workflows. User/system swimlanes show actions, responses, validation, and decision paths.', '', array[]::text[], null, 'Flowchart collection', '', '', '', '/images/e-registered-messaging-system/use-cases.jpg', 'E-Registered Messaging System use-case diagram connecting customer and administrator responsibilities', true, 8, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z')
insert into public.project_sections (id, project_id, section_type, heading, body, sort_order, created_at, updated_at)
values
  ('11111111-1111-4111-8111-111111110101', '11111111-1111-4111-8111-111111111111', 'text', 'A storefront for one-of-one pieces', 'Off The Rack is a digital storefront for one-of-one and upcycled fashion. The experience brings product browsing, product categories, and availability into a responsive website.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110102', '11111111-1111-4111-8111-111111111111', 'text', 'From browsing to the details', 'The storefront connects product listings and product detail views with a custom inquiry flow. Responsive interfaces carry the experience across screen sizes.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110103', '11111111-1111-4111-8111-111111111111', 'text', 'The work behind the storefront', 'Next.js and TypeScript support the frontend. Supabase powers product administration and database integration, with Vercel used for deployment. My role covered UI/UX design, frontend development, and the database/admin connection.', 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('11111111-1111-4111-8111-111111110104', '11111111-1111-4111-8111-111111111111', 'reflection', 'Design meets a working product', 'This project brings interface design, frontend development, and product administration into one responsive storefront. The screenshots and initial wireframe show the interface and the system behind it.', 4, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220101', '22222222-2222-4222-8222-222222222222', 'text', 'An independent point of view', 'This is an independent redesign concept for Marci Metzger Homes, not an official client engagement. The project reworks a real-estate homepage as a clearer editorial experience.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220102', '22222222-2222-4222-8222-222222222222', 'text', 'Give the content room to breathe', 'The redesign uses an editorial visual system within a responsive single-page homepage. The original provided copy and source photography are preserved.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220103', '22222222-2222-4222-8222-222222222222', 'text', 'Built for the browser', 'The frontend uses HTML, CSS, and JavaScript, with Node/npm, Playwright, and Vercel in the project toolset. The experience includes accessible interactions and a responsive layout.', 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('22222222-2222-4222-8222-222222220104', '22222222-2222-4222-8222-222222222222', 'reflection', 'A clearer editorial experience', 'The concept explores how layout, typography, and responsive behavior can reshape a real-estate homepage while retaining its provided content and photography.', 4, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('33333333-3333-4333-8333-333333330101', '33333333-3333-4333-8333-333333333333', 'text', 'Monitoring at a glance', 'The desktop dashboard groups system information, a deployment archive, and connection status. The analytics screen presents mission information and hardware diagnostics as separate areas.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('33333333-3333-4333-8333-333333330102', '33333333-3333-4333-8333-333333333333', 'text', 'Camera and telemetry together', 'The drone-stream screen places a camera view between system-status information and battery, detection, and payload panels. Gauges and status labels provide another way to read the displayed telemetry.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('33333333-3333-4333-8333-333333330103', '33333333-3333-4333-8333-333333333333', 'text', 'A mobile view of the same system', 'The supplied mobile dashboard uses system-summary cards, a recent-flight list, and bottom navigation for home, analytics, and logs.', 3, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('44444444-4444-4444-8444-444444440101', '44444444-4444-4444-8444-444444444444', 'text', 'A game world across screens', 'The home screen combines the selected character, equipment, current quest, and daily quest information. Pixel-art characters and a forest setting carry through the supplied game UI designs.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('44444444-4444-4444-8444-444444440102', '44444444-4444-4444-8444-444444444444', 'text', 'Heroes, gear, and battle', 'The hero screen pairs a selection grid with character details. The equipment screen connects an inventory grid to item information, while the battle screen shows opposing characters, health bars, a timer, and touch controls.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('55555555-5555-4555-8555-555555550101', '55555555-5555-4555-8555-555555555555', 'text', 'A task-management interface', 'The wireframe connects welcome, sign-in, and registration screens with the Task Mate dashboard. Task entries and status summaries establish the structure of the main task view.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('55555555-5555-4555-8555-555555550102', '55555555-5555-4555-8555-555555555555', 'text', 'Following the screen connections', 'Arrows map the paths between navigation, task entry, settings, feedback, help, and logout. Notes beside the screens describe the intended actions and destinations.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('66666666-6666-4666-8666-666666660101', '66666666-6666-4666-8666-666666666666', 'text', 'Account and communication paths', 'Separate flows describe login, sign-up, password recovery, study-together views, and chat. Decision branches show validation, error paths, and the return to the main view.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('66666666-6666-4666-8666-666666660102', '66666666-6666-4666-8666-666666666666', 'text', 'Finding a study partner', 'The main-view diagram maps location permission, user cards, match decisions, and the study-together view. A separate navigation flow links home, study together, chat, and profile destinations.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('77777777-7777-4777-8777-777777770101', '77777777-7777-4777-8777-777777777777', 'text', 'Delivery and retrieval', 'The diagram separates delivery from retrieval. Delivery uses an OTP verification path; retrieval uses an RFID verification path. Each flow includes assigned-locker checks and door or package conditions.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('77777777-7777-4777-8777-777777770102', '77777777-7777-4777-8777-777777777777', 'text', 'The resident''s path', 'The user-side flow starts at the DropSafe dashboard, then moves through login, locker status, OTP generation, delivery notification, and retrieval. The system flow documents the connected status and event updates.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('88888888-8888-4888-8888-888888880101', '88888888-8888-4888-8888-888888888888', 'text', 'A map of the messaging system', 'The use-case diagram separates customer and administrator responsibilities. It covers account access, senders, recipient lists, individual messages, campaigns, tracking, and administration.', 1, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z'),
  ('88888888-8888-4888-8888-888888880102', '88888888-8888-4888-8888-888888888888', 'text', 'Actions and decisions', 'User/system swimlanes separate user actions from system responses. The supplied flows document sender verification, message composition, and campaign scheduling, including validation and return paths.', 2, '2026-10-13T00:00:00Z', '2026-10-13T00:00:00Z')
