  ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2', 'capability', 'Wireframes and responsive interfaces', 'Giving ideas structure, from early layouts to different screen sizes.', 2, true),
  ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3', 'capability', 'Frontend development', 'Turning the interface into a working browser experience.', 3, true),
  ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa4', 'capability', 'Data/backend integration', 'Connecting the interface with the data and administration behind it.', 4, true),
  ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa5', 'capability', 'Deployment and iteration', 'Bringing work to the web and refining the details.', 5, true),
